import 'dart:convert';
import 'package:http/http.dart' as http;
import '../models.dart';
import 'stalker.dart';
String _attr(String line,String key)=>RegExp('$key="([^"]*)"',caseSensitive:false).firstMatch(line)?.group(1)??'';
List<Channel> parseM3u(String text,String sourceId){final out=<Channel>[]; String? name; String logo=''; String group='عام'; for(final raw in const LineSplitter().convert(text.replaceFirst('\uFEFF',''))){final line=raw.trim(); if(line.startsWith('#EXTINF')){final comma=line.indexOf(','); name=comma>=0&&comma<line.length-1?line.substring(comma+1).trim():(_attr(line,'tvg-name').isNotEmpty?_attr(line,'tvg-name'):'بدون اسم'); logo=_attr(line,'tvg-logo'); group=_attr(line,'group-title').trim(); if(group.isEmpty) group='عام';}else if(line.isNotEmpty&&!line.startsWith('#')&&name!=null){out.add(Channel(name:name!,url:line,logo:logo,group:group,sourceId:sourceId));name=null;logo='';group='عام';}} return out;}
Future<List<Channel>> loadChannels(Source s) async {final client=http.Client(); try {if(s.type=='m3u'){final r=await client.get(Uri.parse(s.url),headers:{'Accept':'*/*','User-Agent':'KeefyTV/1.1'}).timeout(const Duration(seconds:60)); if(r.statusCode<200||r.statusCode>=300) throw Exception('فشل تحميل القائمة: HTTP ${r.statusCode}'); final text=utf8.decode(r.bodyBytes,allowMalformed:true); if(!text.contains('#EXTM3U')) throw Exception('الرابط لا يبدو كقائمة M3U صحيحة'); final c=parseM3u(text,s.id); if(c.isEmpty) throw Exception('لم يتم العثور على قنوات في القائمة'); return c;}
if(s.type=='xtream'){final base=s.url.replaceAll(RegExp(r'/+$'),''); Future<dynamic> get(String action) async {final uri=Uri.parse('$base/player_api.php').replace(queryParameters:{'username':s.user,'password':s.pass,if(action.isNotEmpty)'action':action}); final r=await client.get(uri).timeout(const Duration(seconds:45)); if(r.statusCode!=200) throw Exception('Xtream HTTP ${r.statusCode}'); return jsonDecode(utf8.decode(r.bodyBytes,allowMalformed:true));} final cr=await get('get_live_categories'); final sr=await get('get_live_streams'); if(sr is! List) throw Exception('بيانات القنوات غير صحيحة'); final cats=<String,String>{}; if(cr is List){for(final x in cr){cats['${x['category_id']}']='${x['category_name']??'عام'}';}} return [for(final x in sr) Channel(name:'${x['name']??'بدون اسم'}',logo:'${x['stream_icon']??''}',group:cats['${x['category_id']}']??'عام',url:'$base/live/${Uri.encodeComponent(s.user)}/${Uri.encodeComponent(s.pass)}/${x['stream_id']}.${x['container_extension']??'ts'}',sourceId:s.id)];}
final st=Stalker(s); await st.connect(); return st.channels();} finally {client.close();}}
